// site/wiki/figures.mjs — GENERATED FIGURES for wiki articles.
//
// A wiki page writes `[[Figure:name|caption]]` and gets a real diagram. The diagram is DRAWN from data
// in code, not fetched and not generated by an image model, for three reasons:
//   • it has to be right — a diagram that teaches a wrong diagnosis is worse than no diagram;
//   • it has to be the same every time, so a page does not change meaning between loads;
//   • it has to be readable at any size and in print, which means SVG rather than pixels.
// Image-model art has its place elsewhere (the animation lab, the Studio). Instructional figures do not
// get guessed.
//
// Adding a figure: write a function that returns an SVG string, register it in FIGURES, done.
//
//   import { figureHtml, renderFigures, FIGURES, hasFigure } from './figures.mjs'

import { chartSvg } from '../../integrations/plant-deficiency-chart.mjs';

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
));
const f = (n) => Math.round(n * 100) / 100;

const FONT = 'system-ui,-apple-system,Segoe UI,sans-serif';
const INK = '#1d1b17', MUT = '#6b665c', LINE = '#ddd6c8', PAPER = '#f6f4ef';

const text = (x, y, s, { size = 12, weight = 400, anchor = 'middle', fill = INK, style = '' } = {}) =>
  `<text x="${f(x)}" y="${f(y)}" text-anchor="${anchor}" font-family="${FONT}" font-size="${size}" font-weight="${weight}" fill="${fill}"${style ? ` style="${style}"` : ''}>${esc(s)}</text>`;

const frame = (w, h, title, subtitle, body) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${esc(title)}">`
  + `<rect width="${w}" height="${h}" fill="${PAPER}"/>`
  + text(w / 2, 28, title, { size: 17, weight: 800 })
  + (subtitle ? text(w / 2, 48, subtitle, { size: 12, fill: MUT }) : '')
  + body + '</svg>';

// ── the perfumer's note pyramid ─────────────────────────────────────────────────────────────────────
export function notePyramid() {
  const w = 680, h = 400;
  const tiers = [
    { label: 'TOP', when: 'minutes', what: 'citrus, light aldehydes, bergamot, mint', y: 80, wid: 180, fill: '#e9c46a' },
    { label: 'HEART', when: 'hours', what: 'rose, jasmine, spice, geranium', y: 170, wid: 320, fill: '#c2846a' },
    { label: 'BASE', when: 'days', what: 'woods, resins, musks, vanilla, orris', y: 260, wid: 460, fill: '#7a5c45' },
  ];
  const body = tiers.map((t) => {
    const x = w / 2 - t.wid / 2;
    return `<rect x="${f(x)}" y="${t.y}" width="${t.wid}" height="72" rx="8" fill="${t.fill}" opacity="0.9"/>`
      + text(w / 2, t.y + 28, `${t.label} — ${t.when}`, { size: 14, weight: 800, fill: '#1d1b17' })
      + text(w / 2, t.y + 50, t.what, { size: 11.5, fill: '#2b2721' });
  }).join('')
    + `<path d="M 60,86 L 60,326" stroke="${MUT}" stroke-width="1.5" marker-end="url(#ar)"/>`
    + text(44, 206, 'evaporates', { size: 11, fill: MUT, anchor: 'middle', style: 'writing-mode:tb' })
    + text(w / 2, 352, 'A blend judged at the moment of mixing is judged on its top notes alone.', { size: 12, fill: MUT })
    + text(w / 2, 372, 'Perfumers evaluate on a blotter over hours and days — the dry-down.', { size: 12, fill: MUT });
  return frame(w, h, 'The note pyramid', 'Volatility decides when you meet a material — and for how long',
    `<defs><marker id="ar" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="${MUT}"/></marker></defs>${body}`);
}

// ── odour thresholds on a log scale ─────────────────────────────────────────────────────────────────
export function thresholdScale() {
  const w = 760, h = 330;
  // concentration in parts per billion; log10 scale
  const items = [
    { n: 'Grapefruit mercaptan', ppb: 1e-4, c: '#b3261e' },
    { n: 'β-Damascenone (rose)', ppb: 2e-3, c: '#b3261e' },
    { n: 'Geosmin (rain on soil)', ppb: 5e-3, c: '#8a4a28' },
    { n: 'Bell-pepper pyrazine', ppb: 2e-3, c: '#8a4a28' },
    { n: 'Vanillin', ppb: 20, c: '#2f6bb3' },
    { n: 'Linalool', ppb: 6, c: '#2f6bb3' },
    { n: 'Limonene', ppb: 200, c: '#3f8046' },
    { n: 'Ethanol', ppb: 1e8, c: '#3f8046' },
  ].sort((a, b) => a.ppb - b.ppb);
  const lo = -5, hi = 9;                                   // log10 ppb range
  const x0 = 210, x1 = w - 30;
  const X = (ppb) => x0 + (Math.log10(ppb) - lo) / (hi - lo) * (x1 - x0);
  const rows = items.map((it, i) => {
    const y = 90 + i * 27;
    return `<line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="${LINE}" stroke-width="1"/>`
      + `<circle cx="${f(X(it.ppb))}" cy="${y}" r="6" fill="${it.c}"/>`
      + text(x0 - 10, y + 4, it.n, { size: 11.5, anchor: 'end' });
  }).join('');
  const ticks = [-4, -2, 0, 2, 4, 6, 8].map((e) => {
    const x = x0 + (e - lo) / (hi - lo) * (x1 - x0);
    return `<line x1="${f(x)}" y1="78" x2="${f(x)}" y2="${90 + items.length * 27 - 14}" stroke="${LINE}" stroke-dasharray="2 3"/>`
      + text(x, 72, `10${sup(e)}`, { size: 10.5, fill: MUT });
  }).join('');
  return frame(w, h, 'Odour thresholds span twelve orders of magnitude',
    'parts per billion needed before a human nose detects it — note the scale is logarithmic',
    ticks + rows
    + text(w / 2, h - 26, 'This is why blending by weight, without regard to threshold, goes wrong.', { size: 12, fill: MUT })
    + text(w / 2, h - 9, 'A trace of a thiol will rule a mixture that is mostly terpene.', { size: 12, fill: MUT }));
}
const sup = (e) => String(e).replace(/-/g, '⁻').replace(/[0-9]/g, (d) => '⁰¹²³⁴⁵⁶⁷⁸⁹'[+d]);

// ── steam distillation ──────────────────────────────────────────────────────────────────────────────
export function steamDistillation() {
  const w = 720, h = 330;
  const body = [
    // boiler
    `<rect x="60" y="150" width="110" height="90" rx="10" fill="#cfe3ef" stroke="${MUT}"/>`,
    `<path d="M 75,240 Q 115,215 155,240" fill="#9ec9e2"/>`,
    text(115, 262, 'water', { size: 11, fill: MUT }),
    text(115, 142, 'heat', { size: 11, fill: MUT }),
    `<path d="M 100,250 l 0,18 M 115,250 l 0,18 M 130,250 l 0,18" stroke="#b3261e" stroke-width="2"/>`,
    // plant vessel
    `<rect x="215" y="110" width="120" height="130" rx="10" fill="#e8f0e2" stroke="${MUT}"/>`,
    text(275, 254, 'plant material', { size: 11, fill: MUT }),
    `<path d="M 170,170 L 215,170" stroke="${MUT}" stroke-width="2" marker-end="url(#ar2)"/>`,
    text(192, 160, 'steam', { size: 10, fill: MUT }),
    // condenser
    `<path d="M 335,140 L 420,140 L 530,215" stroke="${MUT}" stroke-width="2" fill="none"/>`,
    `<rect x="420" y="128" width="115" height="26" rx="8" fill="#dbe9f3" stroke="${MUT}" transform="rotate(34 420 141)"/>`,
    text(470, 118, 'condenser', { size: 11, fill: MUT }),
    // separator
    `<rect x="540" y="180" width="110" height="110" rx="10" fill="#fff" stroke="${MUT}"/>`,
    `<rect x="542" y="214" width="106" height="74" fill="#cfe3ef"/>`,
    `<rect x="542" y="182" width="106" height="32" fill="#e8d07a"/>`,
    text(595, 202, 'essential oil', { size: 10.5, fill: '#4a3c12' }),
    text(595, 256, 'hydrosol', { size: 10.5, fill: '#23405a' }),
    text(595, 304, 'they separate — oil floats', { size: 10.5, fill: MUT }),
  ].join('');
  return frame(w, h, 'Steam distillation', 'Why an oil that boils above 200 °C comes over below 100 °C',
    `<defs><marker id="ar2" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="${MUT}"/></marker></defs>${body}`
    + text(w / 2, h - 8, 'Two liquids that do not mix each exert their full vapour pressure — so the mixture boils when the SUM reaches atmospheric.', { size: 11.5, fill: MUT }));
}

// ── acid–base extraction ────────────────────────────────────────────────────────────────────────────
export function acidBaseExtraction() {
  const w = 760, h = 340;
  const tube = (x, label, top, bottom, topC, botC, note) => [
    `<rect x="${x}" y="90" width="120" height="150" rx="12" fill="#fff" stroke="${MUT}"/>`,
    `<rect x="${x + 2}" y="92" width="116" height="72" fill="${topC}"/>`,
    `<rect x="${x + 2}" y="164" width="116" height="74" fill="${botC}"/>`,
    `<line x1="${x + 2}" y1="164" x2="${x + 118}" y2="164" stroke="${MUT}" stroke-dasharray="3 3"/>`,
    text(x + 60, 124, top, { size: 11 }),
    text(x + 60, 204, bottom, { size: 11 }),
    text(x + 60, 76, label, { size: 13, weight: 800 }),
    text(x + 60, 262, note, { size: 11, fill: MUT }),
  ].join('');
  const body = tube(60, 'Add acid', 'solvent', 'water — alkaloid salt', '#f2e9d8', '#cfe3ef', 'the base moves DOWN')
    + `<path d="M 200,165 L 250,165" stroke="${MUT}" stroke-width="2" marker-end="url(#ar3)"/>`
    + tube(260, 'Add base', 'solvent — freebase', 'water', '#f6e3a8', '#dde7ef', 'it moves back UP')
    + `<path d="M 400,165 L 450,165" stroke="${MUT}" stroke-width="2" marker-end="url(#ar3)"/>`
    + tube(460, 'Phenols reverse', 'solvent', 'water — phenolate', '#f2e9d8', '#e2d4ef', 'acids go DOWN in base')
    + text(w / 2, 300, 'Charged = water-soluble. Neutral = oil-soluble. Changing pH moves a compound between layers on command.', { size: 12, fill: INK })
    + text(w / 2, 320, 'That one fact separates an alkaloid from fats, sugars and waxes — and from a phenol.', { size: 12, fill: MUT });
  return frame(w, h, 'Acid–base extraction', 'The technique nearly every botanical separation rests on',
    `<defs><marker id="ar3" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="${MUT}"/></marker></defs>${body}`);
}

// ── mobile vs immobile, as a plant ──────────────────────────────────────────────────────────────────
export function mobileImmobile() {
  const w = 620, h = 360;
  const stem = `<path d="M 310,310 L 310,80" stroke="#4e7a41" stroke-width="7" stroke-linecap="round"/>`;
  const leaf = (y, size, fill) => `<ellipse cx="${310 - size - 8}" cy="${y}" rx="${size}" ry="${size * 0.42}" fill="${fill}" transform="rotate(-18 ${310 - size - 8} ${y})"/>`
    + `<ellipse cx="${310 + size + 8}" cy="${y}" rx="${size}" ry="${size * 0.42}" fill="${fill}" transform="rotate(18 ${310 + size + 8} ${y})"/>`;
  const body = stem
    + leaf(110, 26, '#3f8046') + leaf(160, 36, '#3f8046') + leaf(215, 46, '#9fae46') + leaf(275, 54, '#d9d24a')
    + `<path d="M 150,275 L 60,275" stroke="#b9741f" stroke-width="2" marker-end="url(#ar4)"/>`
    + text(58, 268, 'MOBILE shortage', { size: 13, weight: 800, anchor: 'end', fill: '#b9741f' })
    + text(58, 286, 'shows here first', { size: 11.5, anchor: 'end', fill: MUT })
    + text(58, 303, 'N · P · K · Mg', { size: 11.5, anchor: 'end', fill: MUT })
    + `<path d="M 470,110 L 560,110" stroke="#2f6bb3" stroke-width="2" marker-end="url(#ar4b)"/>`
    + text(562, 104, 'IMMOBILE shortage', { size: 13, weight: 800, anchor: 'start', fill: '#2f6bb3' })
    + text(562, 122, 'shows here first', { size: 11.5, anchor: 'start', fill: MUT })
    + text(562, 139, 'Ca · S · Fe · B · Mn', { size: 11.5, anchor: 'start', fill: MUT })
    + text(w / 2, 340, 'The plant robs its old leaves to feed new growth — but only of what it can move.', { size: 12, fill: INK });
  return frame(w, h, 'Where a deficiency shows', 'The one rule that does most of the diagnosis',
    `<defs><marker id="ar4" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#b9741f"/></marker>`
    + `<marker id="ar4b" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#2f6bb3"/></marker></defs>${body}`);
}

// ── the registry ────────────────────────────────────────────────────────────────────────────────────
export const FIGURES = {
  'nutrient-deficiency-chart': { fn: () => chartSvg({ cols: 4, cell: 200 }), alt: 'Cannabis nutrient deficiency chart, leaf by leaf' },
  'mobile-immobile': { fn: mobileImmobile, alt: 'Where a nutrient deficiency shows on a plant' },
  'note-pyramid': { fn: notePyramid, alt: "The perfumer's note pyramid: top, heart and base" },
  'odour-thresholds': { fn: thresholdScale, alt: 'Odour thresholds on a logarithmic scale' },
  'steam-distillation': { fn: steamDistillation, alt: 'How steam distillation works' },
  'acid-base-extraction': { fn: acidBaseExtraction, alt: 'Acid–base extraction between water and solvent' },
};

export const hasFigure = (name) => Object.prototype.hasOwnProperty.call(FIGURES, String(name || '').toLowerCase());

/** one figure as a <figure> block; unknown names render nothing rather than breaking the page */
export function figureHtml(name, caption = '') {
  const key = String(name || '').toLowerCase();
  const fig = FIGURES[key];
  if (!fig) return '';
  let svg = '';
  try { svg = fig.fn(); } catch { return ''; }
  if (!svg) return '';
  // inline, responsive, and never wider than its column
  svg = svg.replace('<svg ', '<svg style="max-width:100%;height:auto" ');
  return `<figure class="wiki-figure" id="fig-${esc(key)}">${svg}`
    + (caption ? `<figcaption>${esc(caption)}</figcaption>` : '')
    + '</figure>';
}

/** expand every [[Figure:name|caption]] in already-rendered HTML */
export function renderFigures(html) {
  return String(html == null ? '' : html).replace(
    /\[\[Figure:([a-z0-9-]+)(?:\|([^\]]*))?\]\]/gi,
    (_, name, caption) => figureHtml(name, caption || ''),
  );
}

export const FIGURE_CSS = `
.wiki-figure{margin:22px 0;padding:0;text-align:center}
.wiki-figure svg{border:1px solid var(--line,#ddd6c8);border-radius:12px;background:#f6f4ef}
.wiki-figure figcaption{color:var(--mut,#6b665c);font-size:13px;margin-top:8px;text-align:center;font-style:italic}
`;
